const inputField=(f)=>{let [name,label,type,def]=f;const lookup={user:db.users.map(x=>[x.id,x.name]),group:db.groups.map(x=>[x.id,x.name]),app:db.apps.map(x=>[x.id,x.name]),reg:db.regs.map(x=>[x.id,x.name]),managed:db.managed.map(x=>[x.id,x.name]),gsa:db.gsa.map(x=>[x.id,x.name]),agent:db.agents.map(x=>[x.id,x.name]),principal:[...db.users.map(x=>[x.id,x.name+' (user)']),...db.groups.map(x=>[x.id,x.name+' (group)'])]};let values=type==='options'?def:(lookup[type]||null);let html=values?`<select name="${name}" required>${values.map(v=>{let pair=Array.isArray(v)?v:[v,v];return `<option value="${safe(pair[0])}" ${pair[0]===def?'selected':''}>${safe(pair[1])}</option>`}).join('')}</select>`:`<input name="${name}" type="${type||'text'}" placeholder="${safe(def||'')}" value="${(type==='email'||type==='number')&&def?safe(def):''}" required>`;return `<label class="field">${label}${html}</label>`};
function modal(kind,title,fields){document.getElementById('modal').innerHTML=`<div class="formmodal" role="dialog" aria-modal="true" aria-label="${safe(title)}"><div class="formcard"><div class="flex between"><h3>${safe(title)}</h3><button class="btn xs" data-action="close-modal">✕ Close</button></div><p class="hint">Changes affect only this simulated training tenant.</p><form id="entity-form" data-kind="${kind}">${fields.map(inputField).join('')}<div class="flex wrap" style="margin-top:18px"><button class="btn primary" type="submit">Save in practice tenant</button><button class="btn" type="button" data-action="close-modal">Cancel</button></div></form></div></div>`;const first=document.querySelector('#entity-form input,#entity-form select');first?.focus()}
function handleForm(form){const kind=form.dataset.kind,vals=Object.fromEntries(new FormData(form).entries());if(!kind)return;const v=vals;let ok=true,msg='Saved in the practice tenant';const nextId=()=>`obj-${Math.random().toString(36).slice(2,9)}`;
 switch(kind){
 case 'user':if(db.users.some(x=>x.email.toLowerCase()===v.email.toLowerCase())){ok=false;msg='That email already exists'}else db.users.push({id:nextId(),name:v.name,email:v.email,type:'Member',role:'',licenses:[],tap:false,revoked:false});break;
 case 'group':if(db.groups.some(x=>x.name===v.name)){ok=false;msg='Group already exists'}else db.groups.push({id:nextId(),name:v.name,members:[]});break;
 case 'member':{let g=db.groups.find(x=>x.id===v.group);if(g&&!g.members.includes(v.user))g.members.push(v.user);break}
 case 'license':{let u=db.users.find(x=>x.id===v.user);if(u&&!u.licenses.includes(v.license))u.licenses.push(v.license);break}
 case 'unit':db.units.push({name:v.name,scope:'Users and groups'});break;
 case 'role':db.roles.push({user:db.users.find(x=>x.id===v.user)?.name||'',role:v.role,scope:v.scope});break;
 case 'guest':db.users.push({id:nextId(),name:v.name,email:v.email,type:'Guest',role:'',licenses:[],tap:false,revoked:false});break;
 case 'attribute':db.attributes[v.resource]=v.value;break;
 case 'tap':{let u=db.users.find(x=>x.id===v.user);if(u)u.tap=true;break}
 case 'policy':db.policies.push({id:nextId(),name:v.name,group:db.groups.find(x=>x.id===v.group)?.name||'Unknown',app:v.app,control:v.control,state:v.state});break;
 case 'gsa':db.gsa.push({id:nextId(),name:v.name,traffic:v.traffic,group:''});break;
 case 'gsa-assign':{let x=db.gsa.find(x=>x.id===v.profile);if(x)x.group=db.groups.find(x=>x.id===v.group)?.name||'';break}
 case 'app':db.apps.push({id:nextId(),name:v.name,sso:'Not configured',assignees:[]});break;
 case 'sso':{let x=db.apps.find(x=>x.id===v.app);if(x)x.sso=v.method;break}
 case 'app-assign':{let x=db.apps.find(x=>x.id===v.app);if(x&&!x.assignees.includes(v.principal))x.assignees.push(v.principal);break}
 case 'reg':db.regs.push({id:nextId(),name:v.name,permissions:[],consented:false});break;
 case 'permission':{let x=db.regs.find(x=>x.id===v.registration);if(x&&!x.permissions.includes(v.permission))x.permissions.push(v.permission);break}
 case 'consent':{let x=db.regs.find(x=>x.id===v.registration);if(x)x.consented=true;break}
 case 'managed':db.managed.push({id:nextId(),name:v.name,grant:''});break;
 case 'grant':{let x=db.managed.find(x=>x.id===v.identity);if(x)x.grant=v.grant;break}
 case 'package':db.packages.push({name:v.name,approval:v.approval,expiry:Number(v.expiry)});break;
 case 'review':db.reviews.push({target:db.groups.find(x=>x.id===v.target)?.name||'',reviewer:v.reviewer,decision:'Awaiting decision'});break;
 case 'pim':db.pim.push({user:db.users.find(x=>x.id===v.user)?.name||'',role:v.role,active:false});break;
 case 'agent':db.agents.push({id:nextId(),name:v.name,owner:v.owner,scope:'',deny:''});break;
 case 'agent-scope':{let a=db.agents.find(x=>x.id===v.agent);if(a){a.scope=v.scope;a.deny=v.deny}break}
 }
 if(ok){record(`${kind}: ${JSON.stringify(v).slice(0,160)}`);save();document.getElementById('modal').innerHTML='';toast(msg,'good');render()}else toast(msg,'bad')
}
function submitSpecial(form){if(form.id==='whatif-form'){const v=Object.fromEntries(new FormData(form).entries());const user=db.users.find(x=>x.id===v.user);const groups=db.groups.filter(g=>g.members.includes(v.user)).map(g=>g.name);let active=[],report=[],isBlocked=false,needsMfa=false,needsDevice=false;for(const p of db.policies){if((p.group==='All users'||groups.includes(p.group))&&(p.app==='All cloud apps'||p.app===v.app)){if(p.state==='Off')continue;let output=p.state==='Report-only'?report:active;output.push(p.name+' — '+p.control);if(p.state==='On'){if(p.control==='Block access')isBlocked=true;if(p.control==='Require MFA')needsMfa=true;if(p.control==='Require compliant device'&&v.device==='Unmanaged')needsDevice=true;}}}let result=isBlocked?'BLOCKED':needsDevice?'DEVICE REQUIREMENT NOT MET':needsMfa?'MFA REQUIRED':'No enforced grant restriction from matching simulated policies';let detail=`Matched active policies: ${active.join('; ')||'none'}. Report-only impact: ${report.join('; ')||'none'}. This is simplified educational logic; real Microsoft policy evaluation has additional conditions and interactions.`;db.whatif={user:user?.name||'',app:v.app,device:v.device,risk:v.risk,result,detail,input:`${user?.name||''} • ${v.app} • ${v.device} • ${v.risk} risk`};record('What If for '+db.whatif.input);save();render();return true}
if(form.id==='duo-form'){let v=Object.fromEntries(new FormData(form).entries());db.duoVerified=v.pattern==='verified';db.duoRecovery=v.recovery==='tested';save();toast('Duo integration assessment saved','good');render();return true}
if(form.id==='nist-form'){let v=Object.fromEntries(new FormData(form).entries());db.nistMapped=v.ial==='IAL2'&&v.aal==='phish'&&v.fal==='not-applicable';save();toast(db.nistMapped?'Risk-assessed design recorded':'Review the distinction between IAL, AAL and FAL',db.nistMapped?'good':'bad');render();return true}
if(form.id==='blueprint-form'){let vals=[...form.querySelectorAll('input[name=control]:checked')].map(x=>x.value);db.blueprint=vals;save();toast('Blueprint saved locally','good');render();return true}return false}

const COACH_TARGETS={userAvery:'new-user',groupFinance:'new-group',financeMember:'group-add-member',licenseAvery:'user-license',unitEast:'new-unit',regionalRole:'assign-role',attrRestricted:'set-attribute',guestPartner:'new-guest',appVendor:'new-app',guestVendor:'assign-app',hybridFixed:'repair-hybrid',passkeys:'toggle-passkey',tapAvery:'new-tap',riskInvestigated:'triage-risk',sessionsRevoked:'user-revoke',caFinance:'new-policy',whatIfTest:'go-whatif',caEnabled:'enable-policy',gsaPrivate:'new-gsa',gsaTarget:'gsa-assign',managedPayroll:'new-managed',managedScoped:'assign-managed',appSaml:'set-app-sso',appFinanceGroup:'assign-app',regFinance:'new-reg',regNarrow:'set-reg-permission',regConsent:'consent-reg',oauthDenied:'deny-oauth',packageContractor:'new-package',reviewFinance:'new-review',reviewRemoved:'review-revoke',pimEligible:'new-pim',pimActive:'activate-pim',logsQueried:'run-logs',diagnosticsOn:'new-diagnostics',deviceCompliant:'device-compliant',proxyCreated:'publish-proxy',blueprintSaved:'export-blueprint',flowUnderstood:'simulate-flow',recoveryPlanned:'recovery-plan',caseSolved:'submit-case',duoVerified:'none',duoRecovery:'none',nistMapped:'none',verifiedIssued:'issue-verified',verifiedChecked:'check-verified',agentCreated:'new-agent',agentScoped:'scope-agent',purviewLabeled:'apply-label',purviewDlp:'enable-dlp',sentinelRule:'create-detection',sentinelIncident:'create-incident',cloudRemediated:'fix-storage',cloudLeast:'fix-owner'};
function highlightCoach(page){const l=LABS.find(x=>x.id===db.activeLab),s=l?.steps[db.labStep||0];if(!s||page!==s.page)return;const action=COACH_TARGETS[s.check];if(!action||action==='none')return;const el=document.querySelector(`.portalmain [data-action="${action}"]`);if(el){el.classList.add('focus');el.title='Guided mission: click here next';}}

