function subTabs(arr,selected){return `<div class="ms-detail-tabs">${arr.map(x=>`<span class="${x===selected?'selected':''}">${x}</span>`).join('')}</div>`}
function userDetail(id){const x=db.users.find(v=>v.id===id);if(!x)return portHeader('User not found','Return to All users','<button class="btn" data-route="portal/users">Back</button>');let memberships=db.groups.filter(g=>g.members.includes(x.id));return portHeader('♙ '+safe(x.name),'User properties and access controls.',`<button class="btn" data-route="portal/users">← All users</button>${rowButtons([['user-license','Assign license',id],['user-revoke','Revoke sessions',id],['user-tap','Issue TAP',id]])}`)+subTabs(['Overview','Groups','Roles','Licenses','Authentication methods'],'Overview')+`<div class="grid2 ms-detail"><div><h3>Identity</h3><div class="ms-propertygrid"><b>Display name</b><span>${safe(x.name)}</span><b>User principal name</b><span>${safe(x.email)}</span><b>Object ID</b><span>${safe(x.id)}</span><b>User type</b><span>${safe(x.type)}</span><b>Account status</b><span>${x.disabled?'Blocked':'Enabled'}</span><b>Last session action</b><span>${x.revoked?'Sessions revoked':'Not revoked'}</span></div><h3>Directory profile</h3><form id="user-detail-form" class="ms-detail-edit"><input type="hidden" name="id" value="${safe(x.id)}"><label class="field">Display name<input name="name" required value="${safe(x.name)}"></label><label class="field">User type<select name="type"><option ${x.type==='Member'?'selected':''}>Member</option><option ${x.type==='Guest'?'selected':''}>Guest</option></select></label><button class="btn primary" type="submit">Save changes</button></form></div><div><h3>Access</h3><p class="small"><b>Groups</b></p>${memberships.map(g=>`<button class="ms-link-row" data-route="portal/group/${g.id}">${safe(g.name)} →</button>`).join('')||'<p class="muted small">No security group membership</p>'}<p class="small"><b>Assigned licenses</b></p><p class="muted small">${safe((x.licenses||[]).join(', ')||'None assigned')}</p><p class="small"><b>Role</b></p><p class="muted small">${safe(x.role||'None')}</p><div class="ms-hint-panel"><b>Why it matters</b><p>Group membership drives authorization and policy targeting. A license unlocks features; it does not automatically authorize access to an application.</p></div></div></div>`}
function groupDetail(id){const x=db.groups.find(v=>v.id===id);if(!x)return portHeader('Group not found','Return to All groups');return portHeader('♟ '+safe(x.name),'Security group settings, membership, and access.',`<button class="btn" data-route="portal/groups">← All groups</button>${rowButtons([['group-add-member','＋ Add member']])}`)+subTabs(['Overview','Members','Roles and administrators','Applications'],'Overview')+`<div class="ms-propertygrid"><b>Name</b><span>${safe(x.name)}</span><b>Group type</b><span>Security</span><b>Object ID</b><span>${safe(x.id)}</span><b>Membership type</b><span>Assigned (training)</span></div><h3>Members (${x.members.length})</h3>${table(['Name','User principal name','Remove'],x.members.map(uid=>{let u=db.users.find(t=>t.id===uid);return `<tr><td><a href="#/portal/user/${uid}" class="ms-record-link">${safe(u?.name||uid)}</a></td><td>${safe(u?.email||'')}</td><td><button class="btn xs" data-action="remove-group-member" data-id="${safe(id+'|'+uid)}">Remove</button></td></tr>`}))}<div class="ms-hint-panel"><b>Why it matters</b><p>Group-based access scales better than assigning hundreds of individuals. Always review membership and how it changes application and CA policy scope.</p></div>`}
function policyDetail(id){const x=db.policies.find(v=>v.id===id);if(!x)return portHeader('Policy not found','Return to Conditional Access');return portHeader('⛨ '+safe(x.name),'Inspect and modify a training Conditional Access policy.',`<button class="btn" data-route="portal/policies">← Policies</button><button class="btn" data-route="portal/whatif">▶ What If</button>`)+subTabs(['Overview','Users','Target resources','Grant controls','Session'],'Overview')+`<div class="ms-propertygrid"><b>Policy state</b><span>${pbadge(x.state)}</span><b>Included users / group</b><span>${safe(x.group)}</span><b>Target resources</b><span>${safe(x.app)}</span><b>Access control</b><span>${safe(x.control)}</span></div><h3>Edit policy</h3><form id="policy-detail-form" class="ms-detail-edit"><input type="hidden" name="id" value="${safe(x.id)}"><label class="field">Policy name<input name="name" required value="${safe(x.name)}"></label><label class="field">Included groups<select name="group">${['All users',...db.groups.map(g=>g.name)].map(z=>`<option ${z===x.group?'selected':''}>${safe(z)}</option>`).join('')}</select></label><label class="field">Target resources<select name="app">${['Finance Reports','Vendor Portal','All cloud apps'].map(z=>`<option ${z===x.app?'selected':''}>${safe(z)}</option>`).join('')}</select></label><label class="field">Access control<select name="control">${['Require MFA','Block access','Require compliant device','Block legacy clients (concept)'].map(z=>`<option ${z===x.control?'selected':''}>${safe(z)}</option>`).join('')}</select></label><label class="field">Policy state<select name="state">${['Off','Report-only','On'].map(z=>`<option ${z===x.state?'selected':''}>${safe(z)}</option>`).join('')}</select></label><div class="ms-hint-panel"><b>Always pilot with report-only</b><p>Changing a real policy can block administrators and employees. In this simulator, you can experiment; production changes require change control and protected emergency access.</p></div><button class="btn primary" type="submit">Save simulated policy</button></form>`}
function submitDetail(form){let v=Object.fromEntries(new FormData(form).entries());if(form.getAttribute('id')==='user-detail-form'){let u=db.users.find(x=>x.id===v.id);if(u){u.name=v.name.trim();u.type=v.type;record('Updated user '+u.name);save();toast('User changes saved','good');render();}return true;}if(form.getAttribute('id')==='policy-detail-form'){let p=db.policies.find(x=>x.id===v.id);if(p){Object.assign(p,{name:v.name.trim(),group:v.group,app:v.app,control:v.control,state:v.state});record('Modified policy '+p.name);save();toast('Policy updated in training tenant','good');render();}return true;}return false}
const _oldPortalAction=portalAction;
portalAction=function(act,el){if(act==='remove-group-member'){const [gid,uid]=(el.dataset.id||'').split('|');const g=db.groups.find(x=>x.id===gid);if(g){g.members=g.members.filter(x=>x!==uid);record('Removed group member '+uid);save();toast('Group membership updated','good');render();}return;}return _oldPortalAction(act,el)};
document.addEventListener('submit',e=>{if(e.target.matches('#user-detail-form,#policy-detail-form')){e.preventDefault();submitDetail(e.target)}});